draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // teacher
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 30);
  ctx.lineTo(W/2 - 100, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 50);
  ctx.lineTo(W/2 - 150, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 50);
  ctx.lineTo(W/2 - 50, H/2 + 30);
  ctx.stroke();

  // student
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 30);
  ctx.lineTo(W/2 + 100, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50);
  ctx.lineTo(W/2 + 150, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 100, H/2 + 50);
  ctx.lineTo(W/2 + 50, H/2 + 30);
  ctx.stroke();

  // teaching arm
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 50);
  ctx.lineTo(W/2 + 100, H/2 + 50 + 20 * Math.sin(t));
  ctx.stroke();

  // student's confused head
  ctx.beginPath();
  ctx.arc(W/2 + 100, H/2 - 20 * Math.sin(t), 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  ctx.restore();
}
